from fastapi import FastAPI, File, Form, UploadFile
from fastapi.testclient import TestClient

app = FastAPI()

@app.post("/upload")
async def upload(file: UploadFile = File(...), form_data: str = Form(...)):
    return {"file": file.filename, "form_data": form_data}

@app.post("/upload_reversed")
async def upload_reversed(form_data: str = Form(...), file: UploadFile = File(...)):
    return {"file": file.filename, "form_data": form_data}

client = TestClient(app)

def test_upload():
    # This one should work
    response = client.post(
        "/upload",
        data={"form_data": "test"},
        files={"file": ("test.txt", b"hello")}
    )
    assert response.status_code == 200
    print("test_upload passed")

def test_upload_reversed():
    # This one is reported to fail with 422
    response = client.post(
        "/upload_reversed",
        data={"form_data": "test"},
        files={"file": ("test.txt", b"hello")}
    )
    print(f"test_upload_reversed status code: {response.status_code}")
    print(f"test_upload_reversed response: {response.json()}")
    assert response.status_code == 200
    print("test_upload_reversed passed")

if __name__ == "__main__":
    try:
        test_upload()
        test_upload_reversed()
    except Exception as e:
        print(f"Error: {e}")
        import sys
        sys.exit(1)

